/bin/zsh -lc "node --input-type=module <<'NODE'
import { chromium, request as req } from '@playwright/test';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
const BIN='/tmp/t2169-candidate/bin/agent-center';
const ID='t2169-har';
const OUT='/Users/oopslink/.agent-center/workers/worker-edb09a0c/var/runtime/worktrees/exec-632dccaa/docs/acceptance/t2169-insight-independent/har-probe';
await mkdir(OUT,{recursive:true});
function teardown(){spawnSync(BIN,['uninstall','test-instance','--id',ID],{stdio:'inherit',encoding:'utf8',timeout:90000});}
teardown();
const installOut=execFileSync(BIN,['install','test-instance','--id',ID,'--with-seed','--workers','1','--output','json'],{encoding:'utf8',timeout:180000});
await writeFile(join(OUT,'install-pack.json'), installOut);
const pack=JSON.parse(installOut);
const base=pack.web_url;
const api="'`${base}/api`;
const slug=pack.signin.org_slug;
const apiCtx=await req.newContext();
const noAuth=await apiCtx.get(`${api}/orgs/${slug}/insights/overview?window=24h`);
const signin=await apiCtx.post(`${api}/auth/signin`,{data:{display_name:pack.signin.display_name,passcode:pack.signin.passcode,org_slug:slug}});
const cookie=/ac_session=([''^;]+)/.exec(signin.headers()['"'set-cookie']||'')?.[1];
const authCtx=await req.newContext({extraHTTPHeaders:{Cookie:"'`ac_session=${cookie}`}});
async function get(path){const r=await authCtx.get(`${api}/orgs/${slug}${path}`); const text=await r.text(); let json=null; try{json=JSON.parse(text)}catch{}; return {status:r.status(), body:json ?? text.slice(0,1000)};}
const probes={
  base, slug, project_id: pack.entity_refs?.project_id,
  no_auth_overview:{status:noAuth.status(), body:(await noAuth.text()).slice(0,500)},
  signin_status: signin.status(),
  overview: await get('"'/insights/overview?window=24h'),
  v2_overview: await get('/insights/v2/overview?window=24h'),
  v2_agents: await get('/insights/v2/agents?window=24h'),
  v2_projects: await get('/insights/v2/projects?window=24h'),
  v2_executions_no_context: await get('/insights/v2/executions?window=24h'),
  collaboration_effects: await get('/insights/collaboration-effects?limit=20'),
};
await writeFile(join(OUT,'api-probes.json'), JSON.stringify(probes,null,2));
const browser=await chromium.launch();
const context=await browser.newContext({viewport:{width:1440,height:980}, recordHar:{path:join(OUT,'insight-pages.har'), content:'embed'}});
await context.addCookies([{name:'ac_session',value:cookie,domain:'127.0.0.1',path:'/',httpOnly:true,sameSite:'Lax'}]);
const page=await context.newPage();
const consoleMessages=[];
page.on('console', msg=>consoleMessages.push({type:msg.type(), text:msg.text()}));
page.on('pageerror', err=>consoleMessages.push({type:'pageerror', text:err.message}));
await page.addInitScript(()=>localStorage.setItem('ac.theme','light'));
for (const [name,path,testId] of [
  ['overview','/insights/overview','page-InsightOverview'],
  ['executions','/insights/executions?window=24h','page-InsightExecutions'],
  ['agents','/insights/agents','page-InsightAgents'],
  ['projects','/insights/projects','page-InsightProjects'],
  ['collaboration','/insights/collaboration','page-InsightCollaboration'],
]) {
  await page.goto("'`${base}/organizations/${encodeURIComponent(slug)}${path}`, {waitUntil:'"'domcontentloaded'});
  await page.getByTestId(testId).waitFor({timeout:12000}).catch(async e=>{ consoleMessages.push({type:'wait-error', text:"'`${name}: ${e.message}`}); });
  await page.waitForTimeout(600);
  await page.screenshot({path:join(OUT,`${name}.png`), fullPage:true});
}
await writeFile(join(OUT,'"'console.json'), JSON.stringify(consoleMessages,null,2));
await context.close();
await browser.close();
await apiCtx.dispose();
await authCtx.dispose();
teardown();
NODE"
